INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-india-qr-code-physical-invoices', 'en', 'QR code now mandatory on physical invoice copies, not just electronic ones', 'India''s GST e-invoicing system now requires the digitally signed QR code generated by the Invoice Registration Portal to be printed on physical copies of invoices, not just retained in the electronic record.', '<h3>🇮🇳 QR code now mandatory on physical invoice copies, not just electronic ones</h3>
<p>India''s e-invoicing system already requires businesses above the ₹5 crore aggregate annual turnover threshold to register B2B invoices on the Invoice Registration Portal (IRP), which validates the data and returns a unique Invoice Reference Number (IRN) alongside a digitally signed QR code embedding key invoice details. What''s changed is a genuinely practical operational point: that QR code must now be printed on physical copies of the invoice as well, not just retained electronically. For a business still issuing any paper invoices to buyers, this is a real change to invoice templates and printing processes, not just a backend data requirement.</p>
<p>This tightening fits a consistent pattern in India''s e-invoicing evolution: the system began in February 2021 covering only businesses above ₹100 crore turnover, and has been progressively extended downward since, now covering any business that crossed ₹5 crore turnover in any financial year since 2017-18. An invoice without a valid IRN and QR code is considered invalid under GST law — a consequence with real teeth, since it means the buyer cannot claim Input Tax Credit on that invoice at all, not merely a compliance technicality for the seller.</p>
<p><strong>What this means for your team:</strong> if any part of your invoicing process still produces printed copies for customers, confirm your template actually renders the QR code correctly on paper, not just in the digital file — a QR code that''s present in your system but missing or unreadable on the printed page can still leave your buyer unable to claim their input tax credit. Given how directly this affects your customers'' own tax position, it''s worth treating as a genuine priority rather than an afterthought.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-04-01-india-30-day-reporting-window', '2025-04-01', '2025-04', 'Since 1 April 2025, taxpayers with aggregate annual turnover of ₹10 crore or more cannot report invoices to the Invoice Registration Portal more than 30 days after the invoice date — the portal simply rejects late submissions outright.', '<h3>🇮🇳 30-day IRN reporting window strictly enforced for large taxpayers</h3>
<p>For taxpayers with aggregate annual turnover of ₹10 crore or more, a strict rule has been in force and remains without any announced relaxation heading into the current financial year: invoices, credit notes, and debit notes must be reported to the Invoice Registration Portal within 30 days of the document''s own date. This isn''t a soft compliance target — if the 30-day window has passed, the IRP simply rejects the submission outright and no IRN is generated at all. An invoice dated 1 January that hasn''t been reported by 30 January cannot be reported after that date, full stop.</p>
<p>This is worth taking seriously precisely because it''s easy to overlook in the day-to-day: unlike a real-time reporting requirement, a 30-day window feels distant when an invoice is first issued, and back-office reporting queues, system outages, or simple oversight can quietly eat into that runway without anyone noticing until it''s already too late. Businesses below the ₹10 crore threshold aren''t subject to this specific rule yet, but the direction of India''s e-invoicing system has consistently been toward tighter timeframes and lower thresholds over time, not looser ones.</p>
<p><strong>What this means for your team:</strong> if your turnover puts you in scope, treat invoice reporting as something with a real, hard deadline attached — not a batch job that can wait for a quiet week. Given a rejected invoice can''t be reported at all once the window closes, and an invoice without a valid IRN denies your buyer their Input Tax Credit, a reporting backlog isn''t just an internal process problem — it becomes your customer''s problem too, which tends to surface as a far more urgent complaint than an internal compliance gap ever would.</p>', 'https://einvoice1.gst.gov.in', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2025-04-01-india-30-day-reporting-window', id FROM countries WHERE name_en = 'India';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-04-01-india-30-day-reporting-window', 'en', '30-day IRN reporting window strictly enforced for large taxpayers', 'Since 1 April 2025, taxpayers with aggregate annual turnover of ₹10 crore or more cannot report invoices to the Invoice Registration Portal more than 30 days after the invoice date — the portal simply rejects late submissions outright.', '<h3>🇮🇳 30-day IRN reporting window strictly enforced for large taxpayers</h3>
<p>For taxpayers with aggregate annual turnover of ₹10 crore or more, a strict rule has been in force and remains without any announced relaxation heading into the current financial year: invoices, credit notes, and debit notes must be reported to the Invoice Registration Portal within 30 days of the document''s own date. This isn''t a soft compliance target — if the 30-day window has passed, the IRP simply rejects the submission outright and no IRN is generated at all. An invoice dated 1 January that hasn''t been reported by 30 January cannot be reported after that date, full stop.</p>
<p>This is worth taking seriously precisely because it''s easy to overlook in the day-to-day: unlike a real-time reporting requirement, a 30-day window feels distant when an invoice is first issued, and back-office reporting queues, system outages, or simple oversight can quietly eat into that runway without anyone noticing until it''s already too late. Businesses below the ₹10 crore threshold aren''t subject to this specific rule yet, but the direction of India''s e-invoicing system has consistently been toward tighter timeframes and lower thresholds over time, not looser ones.</p>
