INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-15-india-threshold-reduction-discussion', '2026-06-15', '2026-06', 'Proposals to lower India''s mandatory e-invoicing threshold from ₹5 crore to ₹2-3 crore have been discussed at multiple GST Council sessions and remain unofficial as of mid-2026 — but the threshold has only ever moved downward since the system began.', '<h3>🇮🇳 Further e-invoicing threshold cuts remain under discussion — not yet notified, but the direction is clear</h3>
<p>India''s mandatory e-invoicing threshold has been reduced repeatedly since the system first launched in February 2021 covering only businesses above ₹100 crore turnover — it now stands at ₹5 crore, and has done so through multiple recent GST Council cycles without a further official cut. That stability shouldn''t be mistaken for permanence: proposals to bring the threshold down to ₹2-3 crore have been discussed at multiple recent Council sessions, and while nothing has been formally notified as of mid-2026, the government''s own stated direction is to make every B2B transaction traceable and digitised over time.</p>
<p>For a business currently sitting between ₹2 crore and ₹5 crore turnover, this genuinely matters as a planning question, not just background policy chatter. The pattern across every previous threshold reduction has been the same: a period of discussion, followed by a notification with a defined implementation date, followed by mandatory compliance from that date — with limited runway once the actual notification lands. Businesses in this turnover band who wait for the official notification before starting any preparation are choosing the shortest possible lead time by default.</p>
<p><strong>What this means for your team:</strong> if your turnover sits in the ₹2-5 crore range, the absence of an official notification today isn''t the same as having time to spare — it''s a temporary window before a rule that''s very likely coming, based on the government''s own consistently stated direction and the track record of every prior threshold cut. Getting IRP registration and invoice-reporting workflows genuinely working now, while there''s no deadline pressure, costs far less than doing the same thing under a live compliance deadline later.</p>', 'https://einvoice1.gst.gov.in', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-15-india-threshold-reduction-discussion', id FROM countries WHERE name_en = 'India';
